def main():
    slugs = [row[0] for row in ITEMS]
    payload = {"schemaVersion": 1, "standard": "XUYI_B2B_SEO_GEO_EDITORIAL", "locales": ["en", "es"], "items": [make_item(row, i, slugs) for i, row in enumerate(ITEMS)]}
    OUT.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"generated {len(payload['items'])} reviewed bilingual mould articles")

if __name__ == "__main__":
    main()
